const normalizeCustomFieldData = (value) => {
  if (Array.isArray(value)) return value;
  if (value && typeof value === "object") return [value];
  return [];
};

const getPlainTextFromHtml = (html) => {
  const value = String(html ?? "");
  return value.replace(/<[^>]+>/g, "").trim();
};

