import React, { useMemo } from "react";
import { Segmented, Tooltip } from "antd";
import { canUseFeature, getUpgradeUrl } from "../../../../../../tier/capabilities";
import { TierLockedWrap } from "../../../../../../tier/TierLockedWrap";

export const FILTER_MODULE_PRO_MESSAGE =
  "This feature is available in Category Ajax Filter Pro.";

export const canUseFilterCustomField = () =>
  canUseFeature("filter_custom_field");
export const canUseFilterShowIcon = () => canUseFeature("filter_show_icon");
export const canUseFilterTermDefault = () =>
  canUseFeature("filter_term_default");
export const canUseFilterTermIcon = () => canUseFeature("filter_term_icon");

export const resolveFilterDataSource = (storedValue) => {
  if (canUseFilterCustomField()) {
    return storedValue === "custom_field" ? "custom_field" : "taxonomy";
  }
  return "taxonomy";
};

export const areFilterTermActionsLocked = () =>
  !canUseFilterTermDefault() || !canUseFilterTermIcon();

export function FilterDataSourceSegment({
  value,
  onChange,
  className = "hoverTabCaf",
}) {
  const customFieldLocked = !canUseFilterCustomField();
  const options = useMemo(
    () => [
      { label: "Taxonomy", value: "taxonomy" },
      {
        label: (
          <span className="caf-filter-data-source-tab-label caf-filter-data-source-tab-label--custom-field">
            Custom Field
            {customFieldLocked ? (
              <span className="caf-builder-tier-locked-wrap__badge caf-filter-data-source-pro-badge">
                Pro
              </span>
            ) : null}
          </span>
        ),
        value: "custom_field",
        disabled: customFieldLocked,
        className: customFieldLocked
          ? "caf-builder-tier-locked-segment-item"
          : undefined,
      },
    ],
    [customFieldLocked]
  );

  const handleChange = (nextValue) => {
    if (nextValue === "custom_field" && customFieldLocked) {
      return;
    }
    onChange(nextValue);
  };

  return (
    <div
      className={`hoverswitchguard caf-filter-data-source-segmented-wrap${
        customFieldLocked ? " caf-filter-data-source-segmented-wrap--locked" : ""
      }`}
    >
      <Segmented
        value={value}
        style={{ marginBottom: 10 }}
        onChange={handleChange}
        className={`${className} caf-filter-data-source-segmented`}
        options={options}
      />
      {customFieldLocked ? (
        <Tooltip
          classNames={{
            root: "caf-builder-tooltip caf-builder-tier-locked-tooltip",
          }}
          placement="topLeft"
          title={
            <span className="caf-builder-tier-locked-section__tooltip-text">
              Custom field filtering is available in Category Ajax Filter Pro.{" "}
              <a
                href={getUpgradeUrl()}
                target="_blank"
                rel="noopener noreferrer"
                className="caf-builder-tier-locked-section__upgrade-link"
              >
                Upgrade to Pro
              </a>
            </span>
          }
        >
          <div
            className="caf-builder-tier-locked-segment-overlay caf-builder-tier-locked-segment-overlay--custom-field"
            aria-hidden="true"
          />
        </Tooltip>
      ) : null}
    </div>
  );
}

export function FilterShowIconLockedSection({ children }) {
  const locked = !canUseFilterShowIcon();
  if (!locked) {
    return children;
  }

  return (
    <TierLockedWrap
      locked
      className="caf-builder-tier-locked-filter-show-icon module-content-tab-row no-pad-0"
      upgradeMessage={FILTER_MODULE_PRO_MESSAGE}
      showProBadge
    >
      {children}
    </TierLockedWrap>
  );
}

export function FilterTermActionsLockedWrap({ children }) {
  const locked = areFilterTermActionsLocked();
  if (!locked) {
    return children;
  }

  return (
    <TierLockedWrap
      locked
      className="caf-builder-tier-locked-term-actions"
      upgradeMessage={FILTER_MODULE_PRO_MESSAGE}
    >
      {children}
    </TierLockedWrap>
  );
}

export const shouldShowFilterTermIconControl = (showIconSetting) =>
  areFilterTermActionsLocked() || showIconSetting === "true";

export const canUseResetModuleIcon = () => canUseFeature("reset_module_icon");

export function ResetModuleIconLockedSection({ children }) {
  const locked = !canUseResetModuleIcon();
  if (!locked) {
    return children;
  }

  return (
    <TierLockedWrap
      locked
      className="caf-builder-tier-locked-reset-icon-section"
      upgradeMessage={FILTER_MODULE_PRO_MESSAGE}
      showProBadge
    >
      {children}
    </TierLockedWrap>
  );
}
