import React, { useState, useEffect } from "react";
import {
  Checkbox,
  Select,
  Modal,
  Button,
  Switch,
  Input,
  Descriptions,
  Segmented,
  Tooltip as AntTooltip,
} from "antd";
import SwitchMain from "./ContentComponents/SwitchMain";
import SelectMain from "./ContentComponents/SelectMain";
import apiClient from "../../../../../api/client";
import LabelIcons from "./ContentComponents/LabelIcons";
import ContentIcons1 from "./ContentComponents/ContentIcons1";
import {
  useResolvedMainBuilderData,
  getResolvedSinglePostData,
} from "./useResolvedMainBuilderData";
import {
  commitFilterModuleSettingsPatch,
  commitFilterModuleReplaceSettings,
} from "./filterSettingsSnapshot";
import { BUILDER_TOOLTIP_CLASS_NAMES } from "../../../../shared/builderTooltipProps";
import SearchModeIcon from "./SearchModeIcon";
import { canUseFeature, getUpgradeUrl } from "../../../../../tier/capabilities";
import { TierLockedWrap } from "../../../../../tier/TierLockedWrap";

const Tooltip = ({ classNames, ...tooltipProps }) => (
  <AntTooltip
    classNames={{
      ...BUILDER_TOOLTIP_CLASS_NAMES,
      ...classNames,
    }}
    {...tooltipProps}
  />
);

const ModuleSearchGenerals = (props) => {
  const { rowindex, columnindex, moduleindex } = props.indexes;
  const mainBuilderData = useResolvedMainBuilderData(props.mainBuilderData);
  const singlePostData = getResolvedSinglePostData(mainBuilderData);
  const canUseSmartAiSearch = canUseFeature("smart_ai_search");
  const canUseSearchCustomField = canUseFeature("search_custom_field");
  const canUseVoiceSearch = canUseFeature("voice_search");

  let settingData = {
    ...props.data[rowindex]?.data[columnindex]?.data[moduleindex]?.settings,
  };

  let meta_fields = singlePostData?.meta_fields;

  //console.log(meta_fields);
  
  let meta_object = [{ label: "Select Custom Field", value: "0" }];

  if (meta_fields) {
    Object.keys(meta_fields)?.map((item, i) => (
      <>{meta_object.push({ value: item, label: item })}</>
    ));
  }
  const [customfield, setCustomfield] = useState(settingData?.custom_field ?? "0");
  const [checkSearch, setCheckSearch] = useState(
    settingData?.search_icon?.is_enable === "false" ? false : true,
  );
  const [checkVoice, setVoiceSearch] = useState(
    settingData?.voice_icon?.is_enable === "false" ? false : true,
  );
  const [checkClear, setClearSearch] = useState(
    settingData?.clear_icon?.is_enable === "false" ? false : true,
  );
  const [label, setLabel] = useState(settingData.search_label);
  const [placeholder, setPlaceholder] = useState(
    settingData.search_placeholder,
  );
  const [headerlabel, setHeaderlabel] = useState(
    settingData.label.is_label === "false" ? false : true,
  );
  const [toggle, setToggle] = useState({
    enable: settingData.enable_toggle === "false" ? false : true,
    close: settingData.close_toggle === "false" ? false : true,
  });
  const [haederlabelInput, setHaederlabelInput] = useState(
    settingData.label.value,
  );
  const [labelIconSwitch, setLabelIconSwitch] = useState(
    settingData?.label?.icons?.visibility,
  );
  const [position, setPosition] = useState(
    settingData?.search_icon?.position ?? "right",
  );
  const [voiceposition, setVoicePosition] = useState(
    settingData?.voice_icon?.position ?? "right",
  );
  const [clearposition, setClearPosition] = useState(
    settingData?.clear_icon?.position ?? "right",
  );
  const [iconsArray, setIconsArray] = useState("");
  const [clearVisible, setClearVisible] = useState(
    settingData?.clear_icon?.visibility ?? "type",
  );
  const [inputValue, setInputValue] = useState(
    settingData?.voice_icon?.placeholder ?? "Listing Now...",
  );
  const [source, setSource] = useState(
    settingData?.source ?? {
      everything: true,
      title: false,
      descriptions: false,
      custom_field: false,
    },
  );
  const [charLimit, setCharLimit] = useState(
    settingData?.char_limit?.is_enable === "true" ? true : false,
  );
  const [limit, setLimit] = useState(settingData?.char_limit?.limit ?? "3");
  const [searchTrigger, setSearchTrigger] = useState(
    settingData?.search_trigger ?? "enter_icon",
  );
  const [searchMode, setSearchMode] = useState(() => {
    const smartEnabled = settingData?.smart_ai_search?.is_enable === "true";
    const keywordDisabled = settingData?.keyword_search?.is_enable === "false";
    if (canUseSmartAiSearch && keywordDisabled && smartEnabled) {
      return "smart_ai_search";
    }
    return "keyword_search";
  });

  const searchModeOptions = [
    {
      label: (
        <Tooltip placement="topLeft" title="Classic keyword matching based on selected sources.">
          <span className="caf-search-mode-tab-label">
            <SearchModeIcon mode="keyword_search" />
            <span>Keyword</span>
          </span>
        </Tooltip>
      ),
      value: "keyword_search",
    },
    {
      label: (
        <Tooltip placement="topLeft" title="AI-assisted semantic search for intent-based results.">
          <span className="caf-search-mode-tab-label caf-search-mode-tab-label--smart-ai">
            <SearchModeIcon mode="smart_ai_search" />
            <span className="caf-ai-search-btn-label">Smart AI Search</span>
            {!canUseSmartAiSearch ? (
              <span className="caf-builder-tier-locked-wrap__badge caf-search-mode-pro-badge">
                Pro
              </span>
            ) : null}
          </span>
        </Tooltip>
      ),
      value: "smart_ai_search",
      disabled: !canUseSmartAiSearch,
      className: !canUseSmartAiSearch
        ? "caf-builder-tier-locked-segment-item"
        : undefined,
    },
  ];

  const iconPositionOptions = [
    {
      label: (
        <Tooltip placement="topLeft" title="Place the icon on the left side of the input.">
          <span>Left</span>
        </Tooltip>
      ),
      value: "left",
    },
    {
      label: (
        <Tooltip placement="topLeft" title="Place the icon on the right side of the input.">
          <span>Right</span>
        </Tooltip>
      ),
      value: "right",
    },
  ];

  const IconPositionTabs = ({ value, onChange }) => (
    <div className="hoverswitchguard">
      <Segmented
        value={value}
        style={{ marginBottom: 10 }}
        onChange={onChange}
        className="hoverTabCaf"
        options={iconPositionOptions}
      />
    </div>
  );

  //const [sourceEverything,setSourceEverything] =useState(settingData?.source_everything === "true" ? true : false)

  const path_url = tc_caf_ajax.plugin_path;
  let icons_url = path_url + "admin/fa-icons/fontawesome-5.json";
  useEffect(() => {
    const fetchIcons = async () => {
      try {
        const response = await apiClient.get(icons_url);
        if (response.data) {
          setIconsArray(response.data);
        }
      } catch (error) {
        console.error("Error ", error);
      }
    };

    fetchIcons();
  }, []);
  // console.log(iconsArray)
  // useEffect(() => {
  //   if (settingData?.label?.icons?.icon == "") {
  //     settingData.label.icons.visibility = false;
  //     items[rowindex].data[columnindex].data[moduleindex]["settings"] =
  //       settingData;
  //     props.onSettingChange(props.data);
  //   }
  // }, [headerlabel]);

  const handleSearch = (checked) => {
    setCheckSearch(checked);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.search_icon = { ...(s.search_icon || {}), is_enable: checked ? "true" : "false" };
      },
    });
  };
  const handleVoice = (checked) => {
    if (!canUseVoiceSearch) {
      return;
    }
    setVoiceSearch(checked);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.voice_icon = { ...(s.voice_icon || {}), is_enable: checked ? "true" : "false" };
      },
    });
  };
  const handleClear = (checked) => {
    setClearSearch(checked);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.clear_icon = { ...(s.clear_icon || {}), is_enable: checked ? "true" : "false" };
      },
    });
  };

  const handleLabel = (val) => {
    setLabel(val);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.search_label = val;
      },
    });
  };

  const handlePlaceholder = (val) => {
    setPlaceholder(val);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.search_placeholder = val;
      },
    });
  };

  const changeInitialData = (data) => {
    setHeaderlabel(data.label.is_label == "false" ? false : true);
    if (data.label.is_label == "false") {
      if (data?.icons) {
        data.icons = {};
      }
    }
    setToggle((prev) => ({
      ...prev,
      enable: data.enable_toggle == "false" ? false : true,
    }));
    if (data.enable_toggle == "false") {
      data.close_toggle = "false";
      setToggle((prev) => ({
        ...prev,
        close: false,
      }));
    }
    commitFilterModuleReplaceSettings({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      nextSettings: data,
    });
  };

  const handleHeaderLabel = (val) => {
    setHaederlabelInput(val);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.label = { ...(s.label || {}), value: val };
      },
    });
  };
  const handlePosition = (val) => {
    setPosition(val);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.search_icon = { ...(s.search_icon || {}), position: val };
      },
    });
  };
  const handleVoicePosition = (val) => {
    setVoicePosition(val);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.voice_icon = { ...(s.voice_icon || {}), position: val };
      },
    });
  };
  const handleClearPosition = (val) => {
    setClearPosition(val);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.clear_icon = { ...(s.clear_icon || {}), position: val };
      },
    });
  };
  const onLabelIconSwitch = (checked) => {
    setLabelIconSwitch(checked);
    let itm = { ...settingData?.label };
    let ic = { ...itm?.icons };
    if (checked === false) {
      ic.icon = "";
      ic.type = "icon";
      ic.position = "before-label";
    }
    ic.visibility = checked;
    itm.icons = { ...itm.icons, ...ic };
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.label = itm;
      },
    });
  };
  const onChangePlaceholder = (val) => {
    setInputValue(val);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.voice_icon = { ...(s.voice_icon || {}), placeholder: val };
      },
    });
  };
  const handleClearVisible = (val) => {
    setClearVisible(val);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.clear_icon = { ...(s.clear_icon || {}), visibility: val };
      },
    });
  };
  // const handleSearchSource1 = (val) => {
  //   setSource(val);
  //   settingData.source = val;
  //   items[rowindex].data[columnindex].data[moduleindex]["settings"] =
  //     settingData;
  //   props.onSettingChange(props.data);
  // };
  const handleCharLimit = (checked) => {
    setCharLimit(checked);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.char_limit = {
          ...(s.char_limit || {}),
          is_enable: checked ? "true" : "false",
        };
      },
    });
  };
  const onChangeLimit = (val) => {
    setLimit(val);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.char_limit = { ...(s.char_limit || {}), limit: val };
      },
    });
  };
  const handleSearchTrigger = (val) => {
    setSearchTrigger(val);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.search_trigger = val;
      },
    });
  };
  const handleSearchModeChange = (mode) => {
    if (mode === "smart_ai_search" && !canUseSmartAiSearch) {
      return;
    }
    setSearchMode(mode);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.smart_ai_search = {
          ...(s.smart_ai_search || {}),
          is_enable: mode === "smart_ai_search" ? "true" : "false",
        };
        s.keyword_search = {
          ...(s.keyword_search || {}),
          is_enable: mode === "keyword_search" ? "true" : "false",
        };
      },
    });
  };
  const handleSearchSource = (checked, key) => {
    if (key === "custom_field" && !canUseSearchCustomField) {
      return;
    }

  if (!checked) {
    const hasAnyOtherTrue = Object.keys(settingData?.source).some(
      (k) => k !== key && settingData?.source[k] === true
    );
    if (!hasAnyOtherTrue && key !== "everything" && settingData?.source?.everything === false) {
      return;
    }
  }

    const base = { ...(settingData?.source || {}) };
    let nextSource = { ...base };

    if(key === "everything" && checked === true){
     setSource((prev) => ({
      ...prev,
      [key]: checked,
      title: false,
      descriptions: false,
      custom_field: false
    }));
    nextSource = {
      ...nextSource,
      [key]: checked,
      title: false,
      descriptions: false,
      custom_field: false,
    };
  }else if(key === "everything" && checked === false){
    setSource((prev) => ({
      ...prev,
      [key]: checked,
      title: true,
    }));
    nextSource = {
      ...nextSource,
      [key]: checked,
      title: true,
    };
  }else{
    setSource((prev) => ({
      ...prev,
      [key]: checked,
    }));
    nextSource = { ...nextSource, [key]: checked };
  }

    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.source = { ...(s.source || {}), ...nextSource };
      },
    });
  };
  const handleChangeCf = (value) => {
    if (!canUseSearchCustomField) {
      return;
    }
    setCustomfield(value);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.custom_field = value;
      },
    });
  };
  return (
    <>
  
      <div className="module-content-tab-row smart-ai-search-row">
        <label className="setting-label-main">Search Type</label>
        <div
          className={`hoverswitchguard caf-search-type-segmented-wrap${
            !canUseSmartAiSearch ? " caf-search-type-segmented-wrap--locked" : ""
          }`}
        >
          <Segmented
            value={searchMode}
            style={{ marginBottom: 10 }}
            onChange={handleSearchModeChange}
            className="hoverTabCaf caf-search-type-segmented"
            options={searchModeOptions}
          />
          {!canUseSmartAiSearch ? (
            <Tooltip
              classNames={{
                root: "caf-builder-tooltip caf-builder-tier-locked-tooltip",
              }}
              placement="topLeft"
              title={
                <span className="caf-builder-tier-locked-section__tooltip-text">
                  Smart AI Search is available in Category Ajax Filter Pro.{" "}
                  <a
                    href={getUpgradeUrl()}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="caf-builder-tier-locked-section__upgrade-link"
                  >
                    Upgrade to Pro
                  </a>
                </span>
              }
            >
              <div
                className="caf-builder-tier-locked-segment-overlay caf-builder-tier-locked-segment-overlay--smart-ai"
                aria-hidden="true"
              />
            </Tooltip>
          ) : null}
        </div>
        <hr className="setting-hr-main"></hr>
      </div>
        {searchMode === "keyword_search" && (
          <div className="module-content-tab-row">
            <label className="setting-label-main">Search In</label>
            <div className="module-content-tab-row caf-design-two-half">
              <Tooltip placement="topLeft" title="Search across all supported fields.">
                <label>Search All Fields</label>
              </Tooltip>
              <Switch
                onChange={(val) => handleSearchSource(val, "everything")}
                checked={source?.everything}
              />
            </div>
            {!source?.everything && (
              <>
                <div className="module-content-tab-row caf-design-two-half">
                  <Tooltip placement="topLeft" title="Include post titles in keyword matching.">
                    <label>Title</label>
                  </Tooltip>
                  <Switch
                    onChange={(val) => handleSearchSource(val, "title")}
                    checked={source?.title}
                  />
                </div>
                <div className="module-content-tab-row caf-design-two-half">
                  <Tooltip placement="topLeft" title="Include post descriptions/excerpts in matching.">
                    <label>Content</label>
                  </Tooltip>
                  <Switch
                    onChange={(val) => handleSearchSource(val, "descriptions")}
                    checked={source?.descriptions}
                  />
                </div>
                <TierLockedWrap
                  locked={!canUseSearchCustomField}
                  className="caf-builder-tier-locked-search-custom-field"
                  upgradeMessage="Custom field search is available in Category Ajax Filter Pro."
                  showProBadge
                >
                  <div className="module-content-tab-row caf-design-two-half">
                    <Tooltip placement="topLeft" title="Include a specific custom field in matching.">
                      <label>Custom Field</label>
                    </Tooltip>
                    <Switch
                      onChange={(val) => handleSearchSource(val, "custom_field")}
                      checked={
                        canUseSearchCustomField ? source?.custom_field : false
                      }
                      disabled={!canUseSearchCustomField}
                    />
                  </div>
                  {(canUseSearchCustomField ? source?.custom_field : true) && (
                    <div className="module-content-tab-row caf-design-two-half">
                      <Tooltip placement="topLeft" title="Pick the custom field used for matching.">
                        <label>Select Custom Field</label>
                      </Tooltip>
                      <Select
                        defaultValue={customfield}
                        style={{
                          width: "100%",
                        }}
                        value={canUseSearchCustomField ? customfield : "0"}
                        onChange={handleChangeCf}
                        options={meta_object}
                        disabled={!canUseSearchCustomField}
                      />
                    </div>
                  )}
                </TierLockedWrap>
              </>
            )}
            <hr className="setting-hr-main"></hr>
          </div>
        )}

      <div className="module-search-text-row">
        <label className="setting-label-main">Text Search</label>
        <div className="module-content-tab-row">
          <div className="module-content-tab-row caf-design-two-half">
            <Tooltip placement="topLeft" title="Show a search icon inside the input.">
              <label>Show Icon</label>
            </Tooltip>
            <Switch
              //checkedChildren="icon"
              //unCheckedChildren="Button"
              onChange={handleSearch}
              checked={checkSearch}
            />
          </div>
          {checkSearch && iconsArray && (
            <>
              <div className="module-content-tab-row">
                <ContentIcons1
                  title="Icons"
                  data={props.data}
                  indexes={props.indexes}
                  iconsArray={iconsArray}
                  onSettingChange={props.onSettingChange}
                  tab="search_icon"
                  type=""
                ></ContentIcons1>
              </div>
              <div className="module-content-tab-row caf-design-two-half">
                <Tooltip placement="topLeft" title="Choose where the icon appears in the field.">
                  <label>Icon Position</label>
                </Tooltip>
                <IconPositionTabs value={position} onChange={handlePosition} />
              </div>
            </>
          )}
        </div>

        <div className="module-content-tab-row caf-design-two-half">
            <Tooltip placement="topLeft" title="Choose when search requests are triggered.">
              <label>Search Trigger</label>
            </Tooltip>
            <Select
              defaultValue={"0"}
              style={{
                width: "100%",
              }}
              onChange={handleSearchTrigger}
              options={[
                {
                  value: "enter_icon",
                  label: "On Enter / Icon Click",
                },
                {
                  value: "typing",
                  label: "On Typing (Live Search)",
                },
              ]}
              value={searchTrigger}
            />
          </div>

        <div className="module-search-min-characters-row">
          <div className="module-content-tab-row caf-design-two-half">
            <Tooltip placement="topLeft" title="Require a minimum number of characters before search.">
              <label>Min Characters</label>
            </Tooltip>
            <Switch onChange={handleCharLimit} checked={charLimit} />
          </div>
          {charLimit && (
            <div className="module-content-tab-row caf-design-two-half">
              <Tooltip placement="topLeft" title="Set the minimum characters required to search.">
                <label>Enter Minimum Characters Limit</label>
              </Tooltip>
              <Input
                type="number"
                value={limit}
                defaultValue={limit}
                onChange={(e) => onChangeLimit(e.target.value)}
              />
            </div>
          )}
        </div>

        <div className="module-content-tab-row caf-design-two-half">
            <Tooltip placement="topLeft" title="Text shown before the user starts typing.">
              <label>Placeholder</label>
            </Tooltip>
            <Input
              onChange={(e) => handlePlaceholder(e.target.value)}
              value={placeholder}
              placeholder={"Search..."}
            />
          </div>

        <hr className="setting-hr-main"></hr>
      </div>
      <TierLockedWrap
        locked={!canUseVoiceSearch}
        className="caf-builder-tier-locked-search-voice module-search-voice-row"
        upgradeMessage="Voice Search is available in Category Ajax Filter Pro."
        showProBadge
      >
        <label className="setting-label-main">Voice Search</label>
        <div className="module-content-tab-row caf-design-two-half">
          <Tooltip placement="topLeft" title="Turn voice search on or off.">
            <label>Enable</label>
          </Tooltip>
          <Switch
            onChange={handleVoice}
            checked={canUseVoiceSearch ? checkVoice : true}
            disabled={!canUseVoiceSearch}
          />
        </div>
        {(canUseVoiceSearch ? checkVoice : true) && iconsArray && (
          <>
            <div className="module-content-tab-row">
              <Tooltip placement="topLeft" title="Select the voice search icon.">
                <label>Voice Icon</label>
              </Tooltip>
              <ContentIcons1
                title="Icons"
                data={props.data}
                indexes={props.indexes}
                iconsArray={iconsArray}
                onSettingChange={props.onSettingChange}
                tab="voice_icon"
                type=""
              ></ContentIcons1>
            </div>
            <div className="module-content-tab-row caf-design-two-half">
              <Tooltip placement="topLeft" title="Choose voice icon placement in the field.">
                <label>Icon Position</label>
              </Tooltip>
              <IconPositionTabs
                value={voiceposition}
                onChange={handleVoicePosition}
              />
            </div>
            <div className="module-content-tab-row caf-design-two-half">
              <Tooltip placement="topLeft" title="Prompt shown for voice search input.">
                <label>Placeholder Text</label>
              </Tooltip>
              <Input
                type="text"
                value={inputValue}
                defaultValue={inputValue}
                onChange={(e) => onChangePlaceholder(e.target.value)}
                disabled={!canUseVoiceSearch}
              />
            </div>
          </>
        )}
        <hr className="setting-hr-main"></hr>
      </TierLockedWrap>

      <div className="module-search-clear-row">
        <label className="setting-label-main">Clear Input</label>
        <div className="module-content-tab-row caf-design-two-half">
          <Tooltip placement="topLeft" title="Turn clear button on or off.">
            <label>Enable</label>
          </Tooltip>
          <Switch
            //checkedChildren="icon"
            //unCheckedChildren="Button"
            onChange={handleClear}
            checked={checkClear}
          />
        </div>
        {checkClear && iconsArray &&(
          <>
            <div className="module-content-tab-row">
              <Tooltip placement="topLeft" title="Select the clear button icon.">
                <label>Clear Icon</label>
              </Tooltip>
              <ContentIcons1
                title="Icons"
                data={props.data}
                indexes={props.indexes}
                iconsArray={iconsArray}
                onSettingChange={props.onSettingChange}
                tab="clear_icon"
                type=""
              ></ContentIcons1>
            </div>
            <div className="module-content-tab-row caf-design-two-half">
              <Tooltip placement="topLeft" title="Choose clear icon placement in the field.">
                <label>Icon Position</label>
              </Tooltip>
              <IconPositionTabs
                value={clearposition}
                onChange={handleClearPosition}
              />
            </div>
            <div className="module-content-tab-row caf-design-two-half">
              <Tooltip placement="topLeft" title="Control when the clear button is visible.">
                <label>Visibility</label>
              </Tooltip>
              <Select
                defaultValue={clearVisible}
                style={{
                  width: "100%",
                }}
                onChange={handleClearVisible}
                options={[
                  {
                    value: "type",
                    label: "On Type",
                  },
                  // {
                  //   value: "voice",
                  //   label: "On Voice",
                  // },
                  // {
                  //   value: "both",
                  //   label: "Both",
                  // },
                  {
                    value: "always",
                    label: "Always Visible",
                  },
                ]}
                value={clearVisible}
              />
            </div>
          </>
        )}
        <hr className="setting-hr-main"></hr>
      </div>

      
      <div className="module-content-tab-row">
        <label className="setting-label-main">Filter Label</label>
        <div className="module-content-tab-row caf-design-two-half">
        <SwitchMain
          label="Enable"
          labelTooltip="Show or hide the filter label."
          property="label"
          property2="is_label"
          onSettingChange={changeInitialData}
          data={settingData}
          currValue={settingData.label.is_label}
        />
        </div>
        {headerlabel && (
          <div
            className="caf-filter-label-inner-row"
            style={{ paddingTop: "15px" }}
          >
            <div className="module-content-tab-row caf-design-two-half">
              <Tooltip
                placement="topLeft"
                title={haederlabelInput && String(haederlabelInput).trim() !== "" ? `Current label: ${haederlabelInput}` : "Set the filter label text."}
              >
                <label>Label Text </label>
              </Tooltip>
              <Input
                onChange={(e) => handleHeaderLabel(e.target.value)}
                value={haederlabelInput}
              />
            </div>
            {iconsArray && (
              <div className="module-content-tab-row caf-builder-show-label-icon">
                <div class="module-content-tab-row caf-design-two-half">
                  <Tooltip placement="topLeft" title="Show an icon next to the filter label.">
                    <label>Show Icon</label>
                  </Tooltip>
                  <div className="module-content-icon-switch">
                    <Switch
                      onChange={onLabelIconSwitch}
                      checked={labelIconSwitch}
                    />
                  </div>
                </div>
                {labelIconSwitch && (
                  <ContentIcons1
                    title="Icons"
                    data={props.data}
                    indexes={props.indexes}
                    iconsArray={iconsArray}
                    onSettingChange={props.onSettingChange}
                    tab="label"
                    type=""
                  ></ContentIcons1>
                )}
              </div>
            )}
            <div className="module-content-tab-row caf-design-two-half">
              <SwitchMain
                label="Enable Collapse"
                labelTooltip="Allow users to expand or collapse this filter."
                property="enable_toggle"
                onSettingChange={changeInitialData}
                data={settingData}
                currValue={settingData.enable_toggle}
              />
            </div>
            {/* <div className="module-content-tab-row caf-design-two-half"> */}
              {toggle.enable && (
                <>
                <div className="module-content-tab-row">
                  <SelectMain
                  label="Toggle Icon Position"
                  labelTooltip="Choose where the toggle icon appears."
                  property="toggle_position"
                  classn={'caf-design-two-half'}
                  options={[
                    {
                      label: "Left",
                      value: "left",
                    },
                    {
                      label: "Right",
                      value: "right",
                    },
                  ]}
                  onSettingChange={changeInitialData}
                  data={settingData}
                />
                </div>
                <div className="module-content-tab-row caf-design-two-half">
                <SwitchMain
                  label="Default Collapsed"
                  labelTooltip="Load this filter in collapsed state by default."
                  property="close_toggle"
                  onSettingChange={changeInitialData}
                  data={settingData}
                  currValue={settingData.close_toggle}
                />
                </div>
                </>
              )}
            {/* </div> */}
          </div>
        )}
      </div>
     
    </>
  );
};

export default ModuleSearchGenerals;
